echo "------------------------------------------------------------------------"
echo "---------------------------------*@@@@@@@-------------------------------"
echo "--------------------------------:*@@@@@@@-------------------------------"
echo "--------------------------------:#@@@@@@@-------------------------------"
echo "---------------------------------+%%%%@@@-------------------------------"
echo "--------------------------------------*@@=------------------------------"
echo "----------------*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@*----------------"
echo "---------------=@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@=---------------"
echo "---------------=@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@=---------------"
echo "---------------=@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@=---------------"
echo "---------------=@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@=---------------"
echo "--------------:-@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@-:--------------"
echo "-------------+%%@@@@@@@@@@@@%+--+@@@@@@@@@@@@%+--#@@@@@@%%+-------------"
echo "-------------#@@@@@@@@%=-=#*-::=*@@@@@@%=-+#+-:-=#@@@@@@@@#-------------"
echo "-------------#@@@@@@@@@+-:-:-=#@@@@@@@@%=-:-:-=#@@@@@@@@@@#-------------"
echo "-------------#@@@@@@@@@@%+-=#@@@@@@@@@@@@%+-=#@@@@@@@@@@@@#-------------"
echo "-------------#@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@#-------------"
echo "-------------=+*@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@*+=-------------"
echo "--------------:-@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@-:--------------"
echo "---------------=@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@=---------------"
echo "----------------#@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@#----------------"
echo "------------------===============------===============------------------"
echo "---------------------------------*####*---------------------------------"
echo "--------------------------------#@@@@@@#--------------------------------"
echo "--------------------------------@@@@@@@@--------------------------------"
echo "-------------------------------+@@@@@@@@+-------------------------------"
echo "-------------------------------%@@@@@@@@%-------------------------------"
echo "-------------------------------%@@@@@@@@%-------------------------------"
echo "--------------------------------+@@@@@@+--------------------------------"
echo "--------------------------------:-#@@#-:--------------------------------"
echo "=----------------------------------==----------------------------------="

if [ -n "$DEBUG" ]; then
  uname -a
  cat /etc/os-release
  lsblk
  env
  echo "$@"
  set -x
fi

usage="usage: $0 <foreman|rails> [args]"

abort() {
  echo "$1"
  exit 42
}

tar -xzf /opt/dependabot-*.tar.gz -C /opt/dependabot --strip-components=1
cd /opt/dependabot || abort "couldn't cd /opt/dependabot"

# Dependabot debug info
echo "dependabot-api SHA:"
printenv GITHUB_SHA

case "$1" in
foreman)
  shift 1
  exec foreman "$@"
  ;;

rails)
  shift 1
  exec bundle exec rails "$@"
  ;;

help)
  abort "$usage"
  ;;

*)
  if [ "$#" -eq 0 ]; then
    exec sh
  else
    exec "$@"
  fi
;;
esac
